// Package agents — test generator agent. v4.2.0 Tier 3.
//
// Generates a regression test that:
//   1. FAILS on the original (buggy) code
//   2. PASSES on the fixed code
//
// This is the SWE-bench FAIL_TO_PASS pattern. The test is generated by a
// SEPARATE LLM call from the fix proposer — the LLM that writes the fix
// does NOT write the test. This prevents the LLM from gaming its own test.
//
// The test runner executor (internal/executors/testrunner.go) runs the test
// against both the original and fixed code in the sandbox. If the test
// fails on original + passes on fixed, the fix is provably correct for
// this specific case.
package agents

import (
        "context"
        "fmt"
        "strings"

        "github.com/karimzakzouk/sentinel/internal/llm"
        "github.com/karimzakzouk/sentinel/internal/schemas"
)

const testGeneratorSystemPrompt = `You are Sentinel's Test Generator agent. Your job is to write a regression test that verifies a code fix is correct.

## Your Task
Given:
- The root cause of a production incident
- The source code (before the fix)
- The proposed fix (search/replace blocks)

Generate a test that:
1. FAILS on the original (buggy) code — reproduces the bug
2. PASSES on the fixed code — verifies the fix

## Test Quality Requirements
- Test the SPECIFIC behavior that was broken, not generic functionality
- Use the framework's idiomatic testing approach:
  - Python: pytest (def test_x():, assert)
  - Go: testing (func TestX(t *testing.T))
  - JavaScript/TypeScript: jest or mocha (describe/it/expect)
  - Java: JUnit (org.junit.jupiter.api.Test)
  - Ruby: minitest or RSpec
  - Rust: #[test]
- The test must be SELF-CONTAINED — no external dependencies (no DB, no network)
- Mock or stub external calls if needed
- Use the same language as the source code

## Test File Location
- Python: tests/test_<function_or_endpoint>.py
- Go: <package>_test.go (same directory as the source)
- JavaScript: __tests__/<name>.test.js or test/<name>.test.js
- Java: src/test/java/.../<Name>Test.java
- Ruby: test/test_<name>.rb
- Rust: same file with #[cfg(test)] or tests/<name>.rs

## Response Format
Return ONLY a JSON object:
{
  "test_file": "tests/test_format_price.py",
  "test_framework": "pytest",
  "test_language": "python",
  "test_content": "import pytest\nfrom app.main import format_price\n\ndef test_format_price_with_integer():\n    result = format_price(50)\n    assert result == \"Price: 50\"\n\ndef test_format_price_with_zero():\n    result = format_price(0)\n    assert result == \"Price: 0\"",
  "test_command": "pytest tests/test_format_price.py -v",
  "description": "Tests that format_price correctly handles integer input (was TypeError: can't concatenate str + int)"
}

No prose before or after the JSON. Start with { and end with }.`

// GeneratedTest is an alias for schemas.GeneratedTest. Kept for backwards
// compatibility — new code should use schemas.GeneratedTest directly.
//
// The canonical type lives in internal/schemas so the executors package
// doesn't have to import agents (fixes LEAK-1 from the architecture audit).
type GeneratedTest = schemas.GeneratedTest

// TestGenerator generates regression tests for code fixes.
type TestGenerator struct {
        router *llm.Router
}

// NewTestGenerator creates a TestGenerator.
func NewTestGenerator(router *llm.Router) *TestGenerator {
        return &TestGenerator{router: router}
}

// Generate produces a regression test for the given incident + fix.
// The test is generated by a separate LLM call from the fix proposer.
func (g *TestGenerator) Generate(ctx context.Context, state *schemas.AgentState) (*GeneratedTest, error) {
        if state.RootCause == nil || state.FixProposal == nil {
                return nil, fmt.Errorf("root cause and fix proposal are required")
        }

        userMsg := g.buildUserMessage(state)
        result, err := g.router.FrontierJSON(ctx, testGeneratorSystemPrompt, userMsg, 4000)
        if err != nil {
                return nil, fmt.Errorf("test generation LLM call failed: %w", err)
        }

        // Parse the result
        testFile, _ := result["test_file"].(string)
        testFramework, _ := result["test_framework"].(string)
        testLanguage, _ := result["test_language"].(string)
        testContent, _ := result["test_content"].(string)
        testCommand, _ := result["test_command"].(string)
        description, _ := result["description"].(string)

        if testFile == "" || testContent == "" {
                return nil, fmt.Errorf("LLM returned empty test file or content")
        }

        return &GeneratedTest{
                TestFile:      testFile,
                TestFramework: testFramework,
                TestLanguage:  testLanguage,
                TestContent:   testContent,
                TestCommand:   testCommand,
                Description:   description,
        }, nil
}

// buildUserMessage constructs the prompt for the test generator.
func (g *TestGenerator) buildUserMessage(state *schemas.AgentState) string {
        var parts []string

        parts = append(parts, fmt.Sprintf("# Service: %s", state.Cluster.Service))
        parts = append(parts, "")

        // Root cause
        parts = append(parts, "## Root Cause")
        parts = append(parts, fmt.Sprintf("- statement: %s", state.RootCause.Statement))
        parts = append(parts, fmt.Sprintf("- category: %s", state.RootCause.Category))
        parts = append(parts, "")

        // Original source code (before fix)
        parts = append(parts, "## Original Source Code (before fix)")
        i := 0
        for path, content := range state.FetchedCode {
                if i >= 5 {
                        break
                }
                parts = append(parts, fmt.Sprintf("### %s", path))
                parts = append(parts, "```")
                if len(content) > 6000 {
                        content = content[:6000]
                }
                parts = append(parts, content)
                parts = append(parts, "```")
                i++
        }
        parts = append(parts, "")

        // Proposed fix
        parts = append(parts, "## Proposed Fix")
        if state.FixProposal.Description != "" {
                parts = append(parts, fmt.Sprintf("Description: %s", state.FixProposal.Description))
        }
        for _, fc := range state.FixProposal.FilesToChange {
                parts = append(parts, fmt.Sprintf("### %s", fc.Path))
                if fc.NewContent != "" {
                        parts = append(parts, "New content:")
                        parts = append(parts, "```")
                        parts = append(parts, fc.NewContent)
                        parts = append(parts, "```")
                }
                for _, ch := range fc.Changes {
                        parts = append(parts, "Search:")
                        parts = append(parts, "```")
                        parts = append(parts, ch.Search)
                        parts = append(parts, "```")
                        parts = append(parts, "Replace:")
                        parts = append(parts, "```")
                        parts = append(parts, ch.Replace)
                        parts = append(parts, "```")
                }
        }
        parts = append(parts, "")

        // Error context (so the test reproduces the right error)
        parts = append(parts, "## Error Context (from pod logs)")
        for _, anomaly := range state.Cluster.Anomalies {
                explanation := anomaly.Explanation
                if len(explanation) > 2000 {
                        explanation = explanation[:2000]
                }
                parts = append(parts, explanation)
        }
        parts = append(parts, "")

        // Language hint
        if lang := detectLanguageFromState(state); lang != "" {
                parts = append(parts, fmt.Sprintf("## Detected Language: %s", lang))
        }

        parts = append(parts, "")
        parts = append(parts, "## Your Task")
        parts = append(parts, "Generate a regression test that FAILS on the original code and PASSES on the fixed code.")
        parts = append(parts, "The test must be self-contained (no external dependencies).")
        parts = append(parts, "Use the file path from '### <path>' above as the import path for the test.")

        return strings.Join(parts, "\n")
}

// detectLanguageFromState extracts the language hint from the incident state.
func detectLanguageFromState(state *schemas.AgentState) string {
        var logs string
        for _, anomaly := range state.Cluster.Anomalies {
                logs += anomaly.Explanation + "\n"
        }
        if logs == "" {
                return ""
        }
        parsed := ParseError(logs)
        if parsed == nil || parsed.Language == "" || parsed.Language == "unknown" {
                return ""
        }
        return parsed.Language
}

// (MarshalJSON removed — the struct's json: tags produce identical output.
// The method was redundant and prevented moving the type to schemas.)
